    lg_bingzhao: {
        audio: 'ext:千秋霸业/Archive:2',
        trigger: {
            global: 'phaseDiscarBegin',
        },
        filter(event, player) {
            if (player == event.player) return false;
            if (player.countCards('h') && event.player.countCards('h')) return true;
            return false;
        },
        content() {
            'step 0';
            var next = game.createEvent('lg_bingzhao', false);
            next.player = player;
            next.target = trigger.player;
            next.setContent(lib.skill.lg_bingzhao.contentx);
        },
        contentx() {
            'step 0';
            if (target.countCards('h') == 0 || player.countCards('h') == 0) {
                event.finish();
                return;
            }
            ('step 1');
            var sendback = function () {
                if (_status.event != event) {
                    return function () {
                        event.resultOL = _status.event.resultOL;
                    };
                }
            };
            if (player.isOnline()) {
                player.wait(sendback);
                event.ol = true;
                player.send(function () {
                    game.me.chooseCard(true).set('glow_result', true).ai = function () {
                        return Math.random();
                    };
                    game.resume();
                });
            } else {
                event.localPlayer = true;
                player.chooseCard(true).set('glow_result', true).ai = function () {
                    return Math.random();
                };
            }
            if (target.isOnline()) {
                target.wait(sendback);
                event.ol = true;
                target.send(function () {
                    var rand = Math.random() < 0.4;
                    game.me.chooseCard(true).set('glow_result', true).ai = function (card) {
                        if (rand) return card.name == 'shan' ? 1 : 0;
                        return card.name == 'shan' ? 0 : 1;
                    };
                    game.resume();
                });
            } else {
                event.localTarget = true;
            }
            ('step 2');
            if (event.localPlayer) {
                event.card1 = result.cards[0];
            }
            if (event.localTarget) {
                var rand = Math.random() < 0.4;
                target.chooseCard(true).set('glow_result', true).ai = function (card) {
                    if (rand) return card.name == 'shan' ? 1 : 0;
                    return card.name == 'shan' ? 0 : 1;
                };
            }
            ('step 3');
            if (event.localTarget) {
                event.card2 = result.cards[0];
            }
            if (!event.resultOL && event.ol) {
                game.pause();
            }
            ('step 4');
            try {
                if (!event.card1) event.card1 = event.resultOL[player.playerid].cards[0];
                if (!event.card2) event.card2 = event.resultOL[target.playerid].cards[0];
                if (!event.card1 || !event.card2) {
                    throw 'err';
                }
            } catch (e) {
                event.finish();
                return;
            }
            if (event.num2 >= 10 || event.num2 <= 4) {
                if (target.countCards('h') > 2) {
                    event.addToAI = true;
                }
            }
            game.broadcastAll(
                function (card1, card2) {
                    card1.classList.remove('glow');
                    card2.classList.remove('glow');
                },
                event.card1,
                event.card2
            );
            ('step 5');
            game.broadcastAll(function () {
                ui.arena.classList.add('thrownhighlight');
            });
            game.addVideo('thrownhighlight1');
            player.$compare(event.card1, target, event.card2);
            ('step 6');
            game.log(player, '展示了', event.card1);
            game.log(target, '展示了', event.card2);
            var color1 = get.color(event.card1);
            var color2 = get.color(event.card2);
            if (color1 == color2) {
                player.draw();
                trigger.player.draw();
            } else player.gainPlayerCard(target, 'he');
            player.$gain2(event.card1);
            target.$gain2(event.card2);
            game.broadcastAll(function () {
                ui.arena.classList.remove('thrownhighlight');
            });
            game.addVideo('thrownhighlight2');
        },
    },
