    lg_xuanhuo: {
        audio: 'ext:千秋霸业/Archive:2',
        enable: 'phaseUse',
        filter(event, player) {
            if ((player.stat[player.stat.length - 1].skill['lg_xuanhuo'] || 0) >= player.maxHp - player.hp) return false;
            return game.hasPlayer(function (current) {
                return current != player && get.distance(player, current, 'attack') <= 1 && current.countCards('h');
            });
        }, //QQQ
        //应变技,出牌阶段限X次,你可以令攻击范围内的其他角色各展示一张手牌,获得其中类别最多的牌.
        //若以此法获得的牌数不等于X,你的下家执行一个额外的出牌阶段(X为你已损失的体力值)
        content() {
            'step 0';
            event.toRespond = game.filterPlayer(function (current) {
                return current != player && get.distance(player, current, 'attack') <= 1 && current.countCards('h');
            });
            player.line(event.toRespond, 'green');
            event.cards = [];
            ('step 1');
            if (event.toRespond.length) {
                var current = event.toRespond.shift();
                event.current = current;
                current.chooseCard('h', true).set('ai', function (card) {
                    var player = _status.event.player;
                    if (card.name == 'du') return 20;
                    if (get.attitude(player, current) < 0) return 5 - get.value(card);
                    return 8 - get.value(card);
                });
            } else {
                event.goto(3);
            }
            ('step 2');
            if (result.cards) {
                var card = result.cards[0];
                event.current.showCards(card);
                event.cards.push(card);
            }
            event.goto(1);
            ('step 3');
            var list = new Object();
            if (Array.isArray(event.cards))
                for (var i of event.cards) {
                    //QQ
                    var t = get.type(i, 'trick');
                    if (list[t] == undefined) list[t] = 1;
                    else list[t]++;
                }
            var max = 0,
                maxType = '';
            for (t in list) {
                if (list[t] > max) {
                    max = list[t];
                    maxType = t;
                }
            }
            event.num = 0;
            if (Array.isArray(event.cards))
                for (var i of event.cards) {
                    //QQ
                    var card = i;
                    if (get.type(card, 'trick') == maxType) {
                        player.gain(card, 'gain2');
                        event.num++;
                    }
                }
            ('step 4');
            if (event.num != player.getDamagedHp()) player.next.phaseUse();
        },
        ai: {
            order: 10,
            result: {
                player(player, current) {
                    if (player.hp == 1) return 0;
                    return 1;
                },
            },
            threaten: 2,
        },
    },
