    lg_guixin: {
        audio: 'ext:千秋霸业/Archive:1',
        trigger: {
            player: 'damageAfter',
        },
        _priority: 10,
        filterTarget(card, player, target) {
            return target.countCards('he') > 0;
        },
        content() {
            'step 0';
            event.targets = game.filterPlayer((p) => p != player && p.countCards('he'));
            event.targets.sortBySeat();
            ('step 1');
            if (!event.targets.length) {
                event.finish();
                return;
            }
            event.target = event.targets.shift();
            if (event.target.countCards('he') == 1) {
                event.target.give(event.target.getCards('he'), player);
                event.redo();
                return;
            }
            var canDiscard = event.target.countDiscardableCards(event.target, 'he') >= 2;
            if (!canDiscard) {
                event.target.chooseCard('he', true, '归心:将一张牌交给' + get.translation(player));
            } else {
                event.target
                    .chooseCard(
                        'he',
                        [1, 2],
                        true,
                        `归心:将一张牌交给${get.translation(player)};或弃置两张牌,令神曹操摸一张牌`,
                        function (card, player) {
                            return ui.selected.cards.length ? [card, ...ui.selected.cards].every((c) => lib.filter.cardDiscardable(c, player)) : true;
                        },
                        function (card, cards) {
                            var evt = _status.event.parent;
                            if (!ui.selected.cards.length) return -get.value(card);
                            if (get.attitude(evt.target, evt.player) < 0) return 7 - get.value(card) + get.value(ui.selected.cards[0]);
                            else return -1;
                        }
                    )
                    .set('complexCard', true);
            }
            ('step 2');
            if (result.bool) {
                if (result.cards.length == 1) {
                    event.target.give(result.cards, player);
                } else {
                    event.target.discard(result.cards);
                    if (target.ai.shown < player.ai.shown) {
                        target.addExpose(0.1);
                    }
                    player.draw();
                }
            }
            event.goto(1);
        },
        contentBackup() {
            'step 0';
            var targets = game.players.slice(0);
            targets.remove(player);
            targets.sort(lib.sort.seat);
            event.targets = targets;
            event.num = 0;
            ('step 1');
            if (event.num < event.targets.length) {
                event.target = event.targets[event.num];
                if (event.target.countDiscardableCards(event.target, 'he') >= 2) {
                    event.target.chooseCard('交给' + get.translation(player) + '一张牌？', 'he').ai = function (card) {
                        if (get.attitude(event.target, player) > 0) return 10 - get.value(card);
                        return 0;
                    };
                } else if (event.target.countCards('h') == 1) {
                    event.target.chooseCard('交给' + get.translation(player) + '一张牌', 'he', true);
                } else {
                    event.num++;
                    event.redo();
                }
            } else {
                event.finish();
            }
            ('step 2');
            if (result.bool) {
                player.gain(result.cards[0]);
                event.target.$give(1, player);
                event.num++;
                event.goto(1);
            } else if (event.target.countDiscardableCards(event.target, 'he') >= 2) {
                event.target.chooseToDiscard('弃置两张牌,令' + get.translation(player) + '摸一张牌', 2, 'he', true);
                event.target.line(player, 'fire');
                player.draw();
                event.num++;
                event.goto(1);
            }
        },
    },
