    lg_chengpi: {
        audio: 'ext:千秋霸业/Archive:1',
        trigger: {
            player: 'phaseBefore',
        },
        forced: true,
        filter(event, player) {
            var hs = player.getCards('h');
            return game.hasPlayer(function (current) {
                if (current != player) {
                    for (var i = 0; i < hs.length; i++) {
                        if (get.info(hs[i]).multitarget) continue;
                        if (lib.filter.targetEnabled2(hs[i], player, current)) {
                            return true;
                        }
                    }
                }
            });
        },
        content() {
            'step 0';
            var hs = player.getCards('h');
            player.chooseTarget(get.prompt('lg_chengpi'), function (card, player, target) {
                if (player == target) return false;
                for (var i = 0; i < hs.length; i++) {
                    if (get.info(hs[i]).multitarget) continue;
                    if (lib.filter.targetEnabled2(hs[i], player, target)) {
                        return true;
                    }
                }
                return false;
            }).ai = function (target) {
                var num = 0,
                    eff = 0,
                    damaged = false;
                for (var i = 0; i < hs.length; i++) {
                    if (get.info(hs[i]).multitarget) continue;
                    var hef;
                    if (get.tag(hs[i], 'damage') && damaged) {
                        hef = -1;
                    } else {
                        hef = get.effect(target, hs[i], player, player);
                    }
                    if (lib.filter.targetEnabled2(hs[i], player, target) && hef > 0) {
                        num++;
                        if (get.attitude(player, target) > 0) {
                            hef /= 1.5;
                            if (get.tag(hs[i], 'damage')) {
                                damaged = true;
                            }
                        }
                        eff += hef;
                    }
                }
                if (!player.needsToDiscard(-num)) {
                    return eff;
                }
                return 0;
            };
            ('step 1');
            if (result.bool) {
                event.target = result.targets[0];
                var num = 0;
                player.chooseCard([1, Infinity], '选择对' + get.translation(result.targets) + '使用的手牌', function (card) {
                    return lib.filter.targetEnabled2(card, player, event.target) && lib.filter.cardEnabled(card, player); //QQQ
                }).ai = function (card) {
                    if (get.effect(event.target, card, player, player) > 0) {
                        if (get.attitude(player, event.target) > 0 && get.tag(card, 'damage')) {
                            for (var i = 0; i < ui.selected.cards.length; i++) {
                                if (get.tag(ui.selected.cards[i], 'damage')) {
                                    return 0;
                                }
                            }
                        }
                        return get.order(card);
                    }
                    return 0;
                };
            } else {
                event.finish();
            }
            ('step 2');
            if (result.bool) {
                player.addSkill('lg_chengpi_draw');
                player.storage.lg_chengpi_draw_num = 0;
                player.storage.lg_chengpi_draw = event.target;
                trigger.cancel();
                event.cards = result.cards.slice(0);
                player.lose(event.cards, ui.special);
            } else {
                event.finish();
            }
            ('step 3');
            if (event.cards.length) {
                if (event.target.isIn()) {
                    player.useCard(event.cards.shift(), event.target);
                } else {
                    event.cards.shift().discard();
                }
                event.redo();
            }
            ('step 4');
            if (player.storage.lg_chengpi_draw_num) {
                player.draw(player.storage.lg_chengpi_draw_num);
            }
            player.removeSkill('lg_chengpi_draw');
            delete player.storage.lg_chengpi_draw;
            delete player.storage.lg_chengpi_draw_num;
        },
        subSkill: {
            draw: {
                trigger: {
                    global: 'damageEnd',
                },
                forced: true,
                popup: false,
                filter(event, player) {
                    return event.player == player.storage.lg_chengpi_draw;
                },
                content() {
                    player.storage.lg_chengpi_draw_num += 2;
                },
            },
        },
        ai: {
            threaten: 1.3,
        },
    },
