    lg_yinfu1: {
        audio: 'ext:千秋霸业/Archive:2',
        trigger: {
            global: 'judge',
        },
        filter(event, player) {
            return event.player != player;
        },
        forced: true,
        content() {
            'step 0';
            player.chooseTarget(get.translation(trigger.player) + '的' + (trigger.judgestr || '') + '判定为' + get.translation(trigger.player.judging[0]) + ',发动此技能？', function (card, player, target) {
                if (target == player) return target.countCards('ej');
                return target.countCards('ej');
            }).ai = function (target) {
                return player == target;
            };
            ('step 1');
            if (result.bool) {
                event.target = result.targets[0];
                if (result.targets[0] == player) {
                    player
                        .chooseCard('选择场上的一张牌代替之', 'ej')
                        .set('ai', function (card) {
                            var trigger = _status.event.getTrigger();
                            var player = _status.event.player;
                            var judging = _status.event.judging;
                            var result = trigger.judge(card) - trigger.judge(judging);
                            var attitude = get.attitude(player, trigger.player);
                            if (attitude == 0 || result == 0) return 0;
                            if (attitude > 0) {
                                return result - get.value(card) / 2;
                            } else {
                                return -result - get.value(card) / 2;
                            }
                        })
                        .set('judging', trigger.player.judging[0]);
                } else {
                    player
                        .choosePlayerCard('选择场上的一张牌代替之', result.targets[0], 'ej')
                        .set('ai', function (button) {
                            var trigger = _status.event.getTrigger();
                            var player = _status.event.player;
                            var judging = _status.event.judging;
                            var result = trigger.judge(button) - trigger.judge(judging);
                            var attitude = get.attitude(player, trigger.player);
                            if (attitude == 0 || result == 0) return 0;
                            if (attitude > 0) {
                                return result - get.value(button) / 2;
                            } else {
                                return -result - get.value(button) / 2;
                            }
                        })
                        .set('judging', trigger.player.judging[0]);
                }
            }
            ('step 2');
            if (result.bool) {
                event.cardx = result.cards[0] || result.links[0];
                event.target.lose(event.cardx);
                player.respond(event.cardx, 'highlight');
            } else {
                event.finish();
            }
            ('step 3');
            if (result.bool) {
                if (trigger.player.judging[0].clone) {
                    trigger.player.judging[0].clone.classList.remove('thrownhighlight');
                    game.broadcast(function (card) {
                        if (card.clone) {
                            card.clone.classList.remove('thrownhighlight');
                        }
                    }, trigger.player.judging[0]);
                    game.addVideo('deletenode', player, get.cardsInfo([trigger.player.judging[0].clone]));
                }
                ui.discardPile.appendChild(trigger.player.judging[0]);
                trigger.player.judging[0] = event.cardx;
                if (!get.owner(event.cardx, 'judge')) {
                    trigger.position.appendChild(event.cardx);
                }
                game.log(trigger.player, '的判定牌改为', event.cardx);
            }
        },
        ai: {
            tag: {
                rejudge: 9,
            },
        },
    },
    lg_yuanxu: {
        marktext2: '缘',
        marktext: '缘',
        intro: {
            name: '缘续',
            content: '你有#枚<缘>标记',
        },
        audio: 'ext:千秋霸业/Archive:2',
        trigger: {
            global: 'recoverEnd',
        },
        filter(event, player) {
            if (player == event.player) return false;
            if (player.countCards('h') && event.player.countCards('h')) return true;
            return false;
        },
        content() {
            'step 0';
            var next = game.createEvent('lg_yuanxu', false);
            next.player = player;
            next.target = trigger.player;
            next.setContent(lib.skill.lg_yuanxu.contentx);
        },
        contentx() {
            'step 0';
            if (target.countCards('h') == 0 || player.countCards('h') == 0) {
                event.finish();
                return;
            }
            ('step 1');
            var sendback = function () {
                if (_status.event != event) {
                    return function () {
                        event.resultOL = _status.event.resultOL;
                    };
                }
            };
            if (player.isOnline()) {
                player.wait(sendback);
                event.ol = true;
                player.send(function () {
                    game.me.chooseCard(true).set('glow_result', true).ai = function () {
                        return Math.random();
                    };
                    game.resume();
                });
            } else {
                event.localPlayer = true;
                player.chooseCard(true).set('glow_result', true).ai = function () {
                    return Math.random();
                };
            }
            if (target.isOnline()) {
                target.wait(sendback);
                event.ol = true;
                target.send(function () {
                    var rand = Math.random() < 0.4;
                    game.me.chooseCard(true).set('glow_result', true).ai = function (card) {
                        if (rand) return card.name == 'shan' ? 1 : 0;
                        return card.name == 'shan' ? 0 : 1;
                    };
                    game.resume();
                });
            } else {
                event.localTarget = true;
            }
            ('step 2');
            if (event.localPlayer) {
                event.card1 = result.cards[0];
            }
            if (event.localTarget) {
                var rand = Math.random() < 0.4;
                target.chooseCard(true).set('glow_result', true).ai = function (card) {
                    if (rand) return card.name == 'shan' ? 1 : 0;
                    return card.name == 'shan' ? 0 : 1;
                };
            }
            ('step 3');
            if (event.localTarget) {
                event.card2 = result.cards[0];
            }
            if (!event.resultOL && event.ol) {
                game.pause();
            }
            ('step 4');
            try {
                if (!event.card1) event.card1 = event.resultOL[player.playerid].cards[0];
                if (!event.card2) event.card2 = event.resultOL[target.playerid].cards[0];
                if (!event.card1 || !event.card2) {
                    throw 'err';
                }
            } catch (e) {
                event.finish();
                return;
            }
            if (event.num2 >= 10 || event.num2 <= 4) {
                if (target.countCards('h') > 2) {
                    event.addToAI = true;
                }
            }
            game.broadcastAll(
                function (card1, card2) {
                    card1.classList.remove('glow');
                    card2.classList.remove('glow');
                },
                event.card1,
                event.card2
            );
            ('step 5');
            game.broadcastAll(function () {
                ui.arena.classList.add('thrownhighlight');
            });
            game.addVideo('thrownhighlight1');
            player.$compare(event.card1, target, event.card2);
            ('step 6');
            game.log(player, '展示了', event.card1);
            game.log(target, '展示了', event.card2);
            var number1 = event.card1.number;
            var number2 = event.card2.number;
            if (number1 == number2) {
                player.addMark('lg_yuanxu', 1);
            } else player.gainPlayerCard('h', target, true);
            player.$gain2(event.card1);
            target.$gain2(event.card2);
            game.broadcastAll(function () {
                ui.arena.classList.remove('thrownhighlight');
            });
            game.addVideo('thrownhighlight2');
        },
    },
