    lg_zhicai2: {
        trigger: {
            player: '',
        },
        forced: true,
        content() {
            'step 0';
            var num1 = 0,
                num2 = 0;
            var choice;
            if (player.hasUnknown(2)) {
                if (game.dead.length == 0) {
                    choice = '阴';
                } else {
                    choice = 'cancel2';
                }
            } else {
                game.countPlayer(function (current) {
                    var att = get.attitude(player, current);
                    if (att > 0) {
                        num1++;
                    } else if (att < 0) {
                        num2++;
                    }
                });
                choice = num1 > num2 ? '阳' : '阴';
            }
            player
                .chooseControl('阳', '阴', 'cancel2', function () {
                    return choice;
                })
                .set('prompt', get.prompt('gwtianbian'))
                .set('choiceList', ['正面制裁', '负面制裁']);
            ('step 1');
            if (result.control != 'cancel2') {
                var list = [];
                for (var i in lib.card) {
                    if (lib.inpile.includes(i) && lib.card[i].selectTarget == -1 && lib.card[i].type != 'equip' && lib.card[i].ai && lib.card[i].ai.tag && lib.card[i].ai.tag.multitarget) {
                        if (lib.card[i].ai.tag.multineg) {
                            if (result.control == '阴') {
                                list.push(i);
                            }
                        } else {
                            if (result.control == '阳') {
                                list.push(i);
                            }
                        }
                    }
                }
                var name = null;
                while (list.length) {
                    name = list.randomRemove();
                    if (
                        game.hasPlayer(function (current) {
                            return player.canUse(name, current);
                        })
                    ) {
                        break;
                    } else {
                        name = null;
                    }
                }
                if (name) {
                    var targets = game.filterPlayer(function (current) {
                        return player.canUse(name, current);
                    });
                    targets.sortBySeat();
                    player.useCard({ name: name }, targets);
                }
            }
        },
    },
    lg_lunhui: {
        audio: 'ext:千秋霸业/Archive:2',
        trigger: {
            global: 'judge',
        },
        filter(event, player) {
            return player.countCards('h') > 0;
        },
        forced: true,
        content() {
            'step 0';
            var str = get.translation(trigger.player) + '的' + (trigger.judgestr || '');
            str += '判定为' + get.translation(trigger.player.judging[0]) + ',';
            str += get.prompt('lg_lunhui');
            var dialogx = [str];
            event.dialogx = dialogx;
            event.cards = [];
            event.targetCards = [];
            event.playerCard = null;
            event.targets2 = [];
            event.num1 = 0;
            player
                .chooseTarget(
                    str,
                    [1, Infinity],
                    function (card, player, target) {
                        if (!target.countCards('h')) return false;
                        if (ui.selected.targets.length == 0) return player == target;
                        return true;
                    },
                    function (target) {
                        var att = get.attitude(_status.event.player, target);
                        if (target == _status.event.player) return 1;
                        return 1 - att;
                    }
                )
                .set('complexTarget', true)
                .set('complexSelect', true);
            ('step 1');
            if (result.bool) {
                event.targets = result.targets;
            } else {
                event.finish();
                return;
            }
            ('step 2');
            if (event.num1 < event.targets.length) {
                event.targets[event.num1].chooseCard(true).ai = function (card) {
                    if (_status.event.getRand() < 0.5) return Math.random();
                    return -get.value(card);
                };
            }
            ('step 3');
            if (result.bool) {
                event.dialogx.push('<div class="text center">【' + get.translation(event.targets[event.num1]) + '】的牌</div>');
                event.dialogx.push(result.cards);
                if (event.targets[event.num1] != player) {
                    event.targetCards.push(result.cards[0]);
                    event.targets2.push(event.targets[event.num1]);
                } else {
                    event.playerCard = result.cards[0];
                }
                event.cards.push(result.cards[0]);
                event.num1++;
                if (event.num1 < event.targets.length) event.goto(2);
            } else {
                event.finish();
                return;
            }
            ('step 4');
            if (event.targets2.length) {
                player.$compareMultiple(event.playerCard, event.targets2, event.targetCards);
            }
            ('step 5');
            player
                .chooseButton(event.dialogx, function (button) {
                    var card = button.link;
                    var trigger = _status.event.getTrigger();
                    var player = _status.event.player;
                    var owner = get.owner(card);
                    var att1 = get.sgn(get.attitude(player, owner));
                    var judging = _status.event.judging;
                    var result = trigger.judge(card) - trigger.judge(judging);
                    var attitude = get.sgn(get.attitude(player, trigger.player));
                    var result2 = result * attitude;
                    if (result2 > 0) {
                        if (att1 <= 0) {
                            //是敌方
                            return result2;
                        }
                    } else if (result2 == 0) {
                        if (att1 <= 0) {
                            //是敌方
                            return 2;
                        }
                    }
                    return 0;
                })
                .set('judging', trigger.player.judging[0])
                .set('filterButton', function (button) {
                    var player = _status.event.player;
                    var card = button.link;
                    var mod2 = game.checkMod(card, player, 'unchanged', 'cardEnabled2', player);
                    if (mod2 != 'unchanged') return mod2;
                    var mod = game.checkMod(card, player, 'unchanged', 'cardRespondable', player);
                    if (mod != 'unchanged') return mod;
                    return true;
                });
            ('step 6');
            if (result.bool) {
                event.forceDie = true;
                player.respond(result.links, 'highlight', 'noOrdering');
                result.cards = result.links;
                var card = result.cards[0];
                event.card = card;
            } else {
                if (Array.isArray(event.cards))
                    for (var i of event.cards) {
                        //QQ
                        var owner = get.owner(i);
                        if (owner) {
                            owner.discard(i);
                        }
                    }
                event.finish();
            }
            ('step 7');
            if (result.bool) {
                if (trigger.player.judging[0].clone) {
                    trigger.player.judging[0].clone.classList.remove('thrownhighlight');
                    game.broadcast(function (card) {
                        if (card.clone) {
                            card.clone.classList.remove('thrownhighlight');
                        }
                    }, trigger.player.judging[0]);
                    game.addVideo('deletenode', player, get.cardsInfo([trigger.player.judging[0].clone]));
                }
                game.cardsDiscard(trigger.player.judging[0]);
                trigger.player.judging[0] = result.cards[0];
                trigger.orderingCards.addArray(result.cards);
                game.log(trigger.player, '的判定牌改为', result.cards[0]);
            }
        },
        ai: {
            rejudge: true,
            tag: {
                rejudge: 0.6,
            },
        },
    },
