    lg_moxian: {
        audio: 'ext:千秋霸业/Sound:2',
        trigger: {
            player: 'phaseUseEnd',
        },
        init(player) {
            if (!player.storage.lg_moxian) player.storage.lg_moxian = undefined;
            if (!player.hasSkill('lg_moxian_1')) player.addSkill('lg_moxian_1');
        },
        filter(event, player) {
            return player.storage.lg_moxian == undefined && player.hp > 0;
        },
        content() {
            'step 0';
            var num = player.hp;
            var map = {};
            var hpList = [];
            for (var i = 1; i < num; i++) {
                var cnn = get.cnNumber(i, true);
                map[cnn] = i;
                hpList.push(cnn);
            }
            hpList.push('cancel');
            event.map = map;
            player
                .chooseControl(hpList)
                .set('prompt', '发动此技能')
                .set('ai', function () {
                    if (game.players.length >= 4) {
                        for (var i of hpList) {
                            if (i == Math.ceil(player.hp / 2)) return i;
                            if (
                                player.countCards('h', function (card) {
                                    return card.name == 'tao';
                                }) > 1
                            )
                                return player.hp - 2;
                            return player.hasCard('shan', 'hes') ? Math.floor(i / 2) : 1;
                        }
                    }
                    return Math.ceil(player.hp / 2);
                });
            ('step 1');
            if (result && result.control) {
                var num = event.map[result.control];
                player.loseHp(num);
                player.draw(num);
                player.storage.lg_moxian = num;
            }
        },
        subSkill: {
            1: {
                audio: 'ext:千秋霸业/Sound:2',
                trigger: {
                    player: 'phaseUseBegin',
                },
                filter(event, player) {
                    return player.storage.lg_moxian != undefined;
                },
                forced: true,
                content() {
                    'step 0';
                    var num = player.storage.lg_moxian;
                    player.recover(num);
                    player
                        .chooseTarget('获得至多' + get.translation(num) + '名角色的至多两张牌', [0, num])
                        .set('complexTarget', true)
                        .set('ai', function (target) {
                            var attitude = get.attitude(player, target);
                            if (attitude > 0) {
                                if (
                                    target.countCards('e', function (card) {
                                        return -get.equipValue(target.getEquip(get.subtype(card)), target);
                                    })
                                )
                                    return false;
                            }
                            return (
                                target.countDiscardableCards(target, 'he', function (card) {
                                    return get.value(card) >= 3;
                                }) >= 1 &&
                                get.attitude(player, target) <= 0 &&
                                target != player
                            );
                        });
                    ('step 1');
                    if (result && result.targets && result.targets.length) {
                        while (result.targets.length) {
                            result.targets.sortBySeat();
                            player.gainPlayerCard('he', 2, result.targets.shift(), true);
                        }
                        player.storage.lg_moxian = undefined;
                    }
                },
                ai: {
                    threaten(player, target) {
                        if (target.hp < 2) return 4;
                        if (target.hp >= 2) return 2;
                    },
                },
            },
        },
    },
