    lg_yizhao: {
        audio: 'ext:千秋霸业/Sound:2',
        trigger: {
            player: ['turnOverBefore', 'linkBefore'],
        },
        init(player) {
            player.storage.lg_yizhao = false;
        },
        filter(event, player) {
            var history = player.getAllHistory('useCard');
            var list = get.inpile(function (name) {
                return (get.type(name) == 'trick' || get.type(name) == 'basic') && player.hasUseTarget({ name: name }, false);
            });
            var list2 = [];
            if (!list.length) return false;
            for (var i = 0; i < history.length; i++) {
                list2.add(history[i].card.name);
            }
            list.removeArray(list2);
            if (!list.length) return false;
            return !player.storage.lg_yizhao;
        },
        limited: true,
        content() {
            'step 0';
            var num = player.maxHp;
            event.count = num;
            player.awakenSkill('lg_yizhao');
            player.useSkill('lg_yizhao1');
            player.storage.lg_yizhao = true;
            ('step 1');
            var history = player.getAllHistory('useCard');
            var list = get.inpile(function (name) {
                var type = get.type(name);
                return (type == 'trick' || type == 'basic') && player.hasUseTarget({ name: name }, false);
            });
            for (var i = 0; i < history.length; i++) {
                list.remove(history[i].card.name);
            }
            if (!list.length) {
                event.finish();
                return;
            }
            var list2 = [];
            for (var i = 0; i < list.length; i++) {
                if (list[i] == 'sha') {
                    list2.push(['基本', '', 'sha']);
                    for (var j of lib.inpile_nature) list2.push(['基本', '', 'sha', j]);
                } else {
                    var type = get.type(list[i]);
                    if (type == 'trick') list2.push(['锦囊', '', list[i]]);
                    if (type == 'basic') list2.push(['基本', '', list[i]]);
                }
            }
            if (list2.length == 1) {
                event._result = { bool: true, links: list2 };
                event.nochoose = true;
            } else {
                var dialog = ui.create.dialog([list2, 'vcard']);
                player
                    .chooseButton(dialog)
                    .set('ai', function (button) {
                        return _status.event.player.getUseValue({ name: button.link[2], nature: button.link[3] });
                    })
                    .set('filterButton', function (button) {
                        return _status.event.player.hasUseTarget({
                            name: button.link[2],
                            nature: button.link[3],
                        });
                    });
            }
            ('step 2');
            if (result.bool) {
                player.chooseUseTarget(
                    {
                        name: result.links[0][2],
                        nature: result.links[0][3],
                    },
                    event.nochoose ? null : true
                );
            } else {
                event.finish();
            }
            ('step 3');
            if (result.bool) {
                event.count--;
                if (event.count > 0) event.goto(1);
            } else {
                event.finish();
            }
        },
        marktext2: '遗',
        marktext: '遗',
        mark: true,
        intro: {
            content: 'limited',
        },
    },
