    lg_chonghuan: {
        audio: 'ext:千秋霸业/Sound:2',
        usable: 1,
        trigger: {
            target: 'useCardToTargeted',
        },
        filter(event, player) {
            if (player == event.player) return false;
            if (player.hp < 1) return false;
            var card = event.card;
            if (get.type(card) == 'basic' || get.type(card) == 'trick') return true;
            return false;
        },
        prompt(event, player) {
            return '发动此技能？';
        },
        check(event, player) {
            if (event.parent.excluded.includes(player)) return false;
            if (get.effect(player, event.card, event.player, player) >= 0) return false;
            var card = event.card;
            var id = player.playerid;
            var map = event.parent.customArgs;
            var need = 1;
            if (get.tag(card, 'respondSha')) {
                if (map[id] && typeof map[id].shaReq == 'number') need = map[id].shaReq;
                if (
                    player.countCards('h', {
                        name: 'sha',
                    }) < need
                ) {
                    return true;
                }
            } else if (get.tag(card, 'respondShan')) {
                if (map[id] && typeof map[id].shanRequired == 'number') need = map[id].shanRequired;
                if (
                    player.countCards('h', {
                        name: 'shan',
                    }) < need
                ) {
                    return true;
                }
            } else if (get.tag(card, 'damage') && card.name != 'huogong') {
                return true;
            }
            return false;
        },
        content() {
            'step 0';
            player.disableEquip(['equip1', 'equip2', 'equip3', 'equip4', 'equip5'].randomGet());
            ('step 1');
            trigger.parent.excluded.add(player);
            ('step 2');
            player
                .chooseTarget(1, get.prompt2('lg_chonghuan'), function (card, player, target) {
                    return target.hp != target.countCards('h');
                })
                .set('ai', function (target) {
                    var base = 1;
                    if (target == player) {
                        base = target.hp > target.countCards('h') ? 2.1 : 0;
                    } else if (target.countCards('h') < target.hp) {
                        base = 2 / target.hp;
                    } else {
                        base = -4 / (Math.max(target.hp, 0.5) * target.countCards('h'));
                    }
                    var num = target.countCards('h') - target.hp;
                    return base * get.attitude(player, target);
                });
            ('step 3');
            if (result.bool && result.targets.length) {
                var target = result.targets[0];
                player.line(target, 'red');
                game.log('lg_chonghuan', player, '令', target, target.countCards('h') < target.hp ? '从牌堆底摸三张牌' : '随机弃置三张手牌');
                if (target.countCards('h') < target.hp) {
                    target.draw(3, 'bottom');
                } else {
                    target.randomDiscard(3, 'h');
                }
            }
        },
        ai: {
            threaten(viewer, player) {
                if (player.countCards('h') < player.hp - 1) return 0.7;
            },
        },
    },
