    lg_baoshu: {
        marktext2: '梳',
        marktext: '梳',
        intro: {
            name: '宝梳',
            content: '你有#枚<宝梳>标记',
        },
        audio: 'ext:千秋霸业/Sound:2',
        trigger: {
            player: ['phaseJieshuBegin'],
        },
        filter(event, player, name) {
            var num = 0;
            return true;
        },
        content() {
            'step 0';
            var num = Math.min(9, Math.max(1, player.getDamagedHp()));
            if (
                player.getHistory('sourceDamage', function (evt) {
                    return evt.num > 0; // && evt.card && evt.card.name == 'sha';
                }).length
            ) {
                player.draw(num);
                event.finish();
            } else {
                var cards = get.cards(2 + num);
                var next2 = player.next;
                var ongoing = true;
                while (next2 && next2 != player && ongoing) {
                    if (!next2.isTurnedOver()) {
                        ongoing = false;
                    } else {
                        next2 = next2.next;
                    }
                }
                if (!next2) next2 = player.next;
                var next = player.chooseToMove();
                next.set('list', [['置于牌堆顶', cards], ['获得的牌'], ['置于牌堆底']]);
                next.set('prompt', '宝梳:获得其中的至多' + get.cnNumber(num) + '张牌,将其余的牌置于牌堆顶或牌堆底');
                next.set('num', num);
                next.set('next2', next2);
                next.set('filterMove', function (from, to, moved) {
                    var num = _status.event.num || 1;
                    if (to == 1 && moved[1].length >= num) return false;
                    return true;
                });
                next.set('filterOk', function (moved) {
                    var num = _status.event.num || 1;
                    return moved[1].length <= num;
                });
                next.processAI = function (list) {
                    var cards = list[0][1],
                        player = _status.event.player,
                        target = _status.event.next2,
                        num = _status.event.num;
                    cards.sort(function (a, b) {
                        return get.value(b, player) - get.value(a, player);
                    });
                    var togain = [];
                    for (var i = 0; i < num; i++) {
                        if (get.value(cards[i], player) > 0) togain.push(cards[i]);
                    }
                    cards.removeArray(togain);
                    const top = [],
                        bottom = cards;
                    for (const i of target.getCards('j')) {
                        const judge = get.judge(i);
                        bottom.sort((a, b) => (judge(b) - judge(a)) * att); //态度大于0价值高的牌放前面
                        if (bottom.length) {
                            top.push(bottom.shift());
                        }
                    }
                    bottom.sort((a, b) => (get.value(b) - get.value(a)) * att); //态度大于0价值高的牌放前面
                    while (bottom.length) {
                        top.push(bottom.shift());
                    }
                    return [top, togain, cards];
                };
            }
            ('step 1');
            if (result.bool) {
                var togain = result.moved[1];
                player.gain(togain, 'draw');
            }
            ('step 2');
            var top = result.moved[0];
            var bottom = result.moved[2];
            top.reverse();
            for (var i = 0; i < top.length; i++) {
                ui.cardPile.insertBefore(top[i], ui.cardPile.firstChild);
            }
            for (var i = 0; i < bottom.length; i++) {
                ui.cardPile.appendChild(bottom[i]);
            }
            player.popup(get.cnNumber(top.length) + '顶' + get.cnNumber(bottom.length) + '底');
            game.log(player, '将' + get.cnNumber(top.length) + '张牌置于牌堆顶');
            game.log(player, '将' + get.cnNumber(bottom.length) + '张牌置于牌堆底');
            ('step 3');
            player.addMark('lg_baoshu', 2);
            game.updateRoundNumber();
        },
    },
