    lg_chuilian: {
        audio: 'ext:千秋霸业/Sound:2',
        enable: 'phaseUse',
        mark: true,
        limited: true,
        intro: {
            content: 'limited',
        },
        init(player) {
            if (typeof player.storage.lg_chuilian != 'boolean') player.storage.lg_chuilian = false;
        },
        filter(event, player) {
            return (
                !player.storage.lg_chuilian &&
                game.hasPlayer(function (target) {
                    if (target == player) return false;
                    return (
                        target.countCards('e', function (cardx) {
                            return player.canEquip(cardx);
                        }) > 0 ||
                        target.countCards('j', function (cardx) {
                            return player.canAddJudge(cardx);
                        }) > 0
                    );
                })
            );
        },
        selectTarget: -1,
        multitarget: true,
        multiline: true,
        line: 'fire',
        content() {
            'step 0';
            player.awakenSkill('lg_chuilian');
            event.bool = true;
            event.list = [];
            ('step 1');
            var targets = {
                all: [],
            };
            for (var i = 1; i < 6; i++) {
                if (!player.isEmpty(i)) continue;
                targets['equip' + i] = game.filterPlayer(function (target) {
                    if (get.attitude(player, target) > 0) return false;
                    var equip = target.getEquip(i);
                    if (equip && player.canEquip(equip) && get.equipValue(equip, player) > 0) {
                        targets.all.add(target);
                        return true;
                    }
                    return false;
                });
            }
            player
                .chooseTarget(1, event.bool, event.bool ? '选择一名其他角色' : '重复此流程？', function (card, player, target) {
                    if (target == player || _status.event.list.includes(target)) return false;
                    return (
                        target.countCards('e', function (cardx) {
                            return player.canEquip(cardx);
                        }) > 0 ||
                        target.countCards('j', function (cardx) {
                            return player.canAddJudge(cardx);
                        }) > 0
                    );
                })
                .set('ai', function (target) {
                    var player = _status.event.player;
                    var targets = _status.event.map;
                    var result = function (current) {
                        var count = -1;
                        for (var i in targets) {
                            if (targets[i].includes(current)) count++;
                        }
                        return count;
                    };
                    var count = result(target);
                    if (count <= 0) return -1;
                    if (get.attitude(player, target) <= 0) return 1 / count;
                    return -1;
                })
                .set('list', event.list)
                .set('map', targets);
            ('step 2');
            if (result.bool) {
                var target = result.targets[0];
                event.target = target;
                event.list.push(target);
                player
                    .choosePlayerCard(target, '将' + get.translation(target) + '场上的一张牌移至给你', 'ej', true, function (button) {
                        var player = _status.event.player;
                        var card = button.link;
                        var target = _status.event.parent.target;
                        if (get.position(card) == 'j') return -1;
                        if (get.value(card, target) < 0 && get.value(card, player) > 0) {
                            return get.value(card, player) + get.sgn(get.attitude(player, target)) * get.value(card, target);
                        } else {
                            return get.value(card, player);
                        }
                        return -1;
                    })
                    .set('filterButton', function (button) {
                        if (get.position(button.link) == 'e') return player.canEquip(button.link, false);
                        if (get.position(button.link) == 'j') return player.canAddJudge(button.link);
                    });
            } else {
                event.finish();
            }
            ('step 3');
            var card = result.cards[0];
            target.$give(card, player);
            if (get.position(card) == 'e') {
                player.equip(card);
            } else {
                player.addJudge(card);
            }
            ('step 4');
            event.bool = false;
            event.goto(1);
        },
        ai: {
            order(item, player) {
                var targets = {
                    all: [],
                };
                for (var i = 1; i < 6; i++) {
                    if (!player.isEmpty(i)) continue;
                    targets['equip' + i] = game.filterPlayer(function (target) {
                        if (get.attitude(player, target) > 0) return false;
                        var equip = target.getEquip(i);
                        if (equip && player.canEquip(equip) && get.equipValue(equip, player) > 0) {
                            targets.all.add(target);
                            return true;
                        }
                        return false;
                    });
                }
                var result = function (target) {
                    var count = -1;
                    for (var i in targets) {
                        if (targets[i].includes(target)) count++;
                    }
                    return count;
                };
                var targets1 = targets.all.slice(0);
                targets1.sort(function (a, b) {
                    return result(a) - result(b);
                });
                var targets2 = [];
                var total = 0;
                for (var i = 0; i < targets1.length; i++) {
                    var current = targets1[i];
                    var es = current.getCards('e');
                    for (var j = 0; j < targets2.length; j++) {
                        for (var k = 0; k < es.length; k++) {
                            if (!player.canEquip(es[k]) || targets2[j].getEquip(get.subtype(es[k]))) es.splice(k--, 1);
                        }
                    }
                    if (es.length) {
                        total += 1;
                        targets2.add(current);
                    }
                }
                if (total >= 2) return 20;
                if (player.hp <= 1 && total > 0) return 2;
                return -1;
            },
            result: {
                player(player) {
                    return 1;
                },
            },
        },
    },
