    lg_taishi: {
        audio: 'ext:千秋霸业/Sound:2',
        trigger: {
            global: ['phaseUseEnd'],
        },
        filter(event, player) {
            var count = 2;
            var players = game.filterPlayer();
            for (var i = 0; i < players.length; i++) {
                if (players[i].getHistory('useCard').length) count -= 1;
            }
            return count == 0;
        },
        content() {
            'step 0';
            event.player1 = null;
            event.player2 = null;
            var players = game.filterPlayer();
            for (var i = 0; i < players.length; i++) {
                if (players[i].getHistory('useCard').length) {
                    if (event.player1 == null) event.player1 = players[i];
                    else event.player2 = players[i];
                }
            }
            ('step 1');
            player
                .chooseControl('①', '②', function (event, player) {
                    var att1 = get.attitude(player, event.player1);
                    var att2 = get.attitude(player, event.player2);
                    if (att1 <= 0 && att2 <= 0) return '②';
                    if (att1 >= 0 && att2 >= 0) return '①';
                    if (event.player1 == player || event.player2 == player) {
                        var cards = [];
                        game.countPlayer2(function (current) {
                            current.getHistory('lose', function (evt) {
                                if (evt.position == ui.discardPile) {
                                    for (var i = 0; i < evt.cards.length; i++) {
                                        if (evt.cards[i].name != 'sha') cards.add(evt.cards[i]);
                                    }
                                }
                            });
                        });
                        game.getGlobalHistory('cardMove', function (evt) {
                            if (evt.name == 'cardsDiscard') {
                                for (var i = 0; i < evt.cards.length; i++) {
                                    if (evt.cards[i].name != 'sha') cards.add(evt.cards[i]);
                                }
                            }
                        });
                        if (player.hp <= 1 || player.countCards('h') <= 2) return '①';
                        if (
                            player.countCards('h', {
                                type: 'sha',
                            }) > 0
                        )
                            return '②';
                        if (Math.random() > 0.5) return '①';
                        return '②';
                    }
                    var player3 = null;
                    if (att1 >= 0) player3 = event.player1;
                    else player3 = event.player2;
                    if (player3.hp <= 1 || player3.countCards('h') <= 2) return '①';
                    if (Math.random() > 0.5) return '①';
                    return '②';
                })
                .set('prompt', '令' + get.translation(event.player1) + '与' + get.translation(event.player2) + '各摸两张牌;或各弃置两张牌');
            ('step 2');
            if (result.control) {
                if (result.control == '①') {
                    event.player1.draw(2);
                    event.player2.draw(2);
                    event.goto(4);
                } else {
                    event.player1.chooseToDiscard('弃置两张牌', 2, 'he', true).ai = function (card) {
                        if (card.name == 'du' && player.hp == 1) return 1;
                        if (event.player1 == player && card.name != 'sha') return 30;
                        if (event.player2 == player && card.name != 'sha') return 13;
                        return 20 - get.value(card);
                    };
                    event.goto(3);
                }
            }
            ('step 3');
            event.player2.chooseToDiscard('弃置两张牌', 2, 'he', true).ai = function (card) {
                if (card.name == 'du' && player.hp == 1) return 1;
                if (event.player2 == player && card.name != 'sha') return 30;
                if (event.player1 == player && card.name != 'sha') return 13;
                return 20 - get.value(card);
            };
            ('step 4');
            var cards = [];
            game.countPlayer2(function (current) {
                current.getHistory('lose', function (evt) {
                    if (evt.position == ui.discardPile) {
                        for (var i = 0; i < evt.cards.length; i++) {
                            if (evt.cards[i].name != 'sha') cards.add(evt.cards[i]);
                        }
                    }
                });
            });
            game.getGlobalHistory('cardMove', function (evt) {
                if (evt.name == 'cardsDiscard') {
                    for (var i = 0; i < evt.cards.length; i++) {
                        if (evt.cards[i].name != 'sha') cards.add(evt.cards[i]);
                    }
                }
            });
            if (cards.length && (event.player1 == player || event.player2 == player)) player.gain(cards, 'gain2');
        },
    },
