    lg_sanglun1: {
        trigger: {
            player: '',
        },
        forced: true,
        content() {
            'step 0';
            var num = game.me.getCards('h').reduce((a, b) => (a < b.number ? b.number : a), 0);
            player
                .chooseTarget('与一名其他角色进行拼点？', function (card, player, target) {
                    return player.canCompare(target);
                })
                .set('ai', function (target) {
                    var player = _status.event.player;
                    var eff = -get.attitude(player, target) - get.attitude(player, player);
                    var playerExpect = ((_status.event.num - 1) / 13) ** target.countCards('h');
                    eff += 2 * playerExpect * get.attitude(player, player) + 2 * (1 - playerExpect) * get.attitude(player, target) + 1;
                    return eff;
                })
                .set('num', num);
            ('step 1');
            if (result.bool) {
                event.target = result.targets[0];
                player.chooseToCompare(event.target);
            } else {
                event.finish();
            }
            ('step 2');
            if (result.bool) {
                player.draw();
            } else {
                event.target.draw();
            }
        },
    },
    lg_ganhuai: {
        audio: 'ext:千秋霸业/Sound:2',
        trigger: {
            player: 'dyingAfter',
        },
        filter(event, player) {
            if (game.online) {
                return true;
            }
            var suits = ['heart', 'club', 'spade', 'diamond'];
            var cards = player.getCards('h');
            for (var i = 0; i < cards.length; i++) {
                if (suits.includes(cards[i].suit)) suits.remove(cards[i].suit);
            }
            return suits.length;
        },
        check(event, player) {
            return true;
        },
        content() {
            player.showHandcards();
            var suits = ['heart', 'club', 'spade', 'diamond'];
            event.cards = player.getCards('h');
            if (Array.isArray(event.cards))
                for (var i of event.cards) {
                    //QQ
                    if (suits.includes(i.suit)) suits.remove(i.suit);
                }
            if (suits.length) player.draw(suits.length);
        },
    },
